424	-- HYPERTABLE: meal logs (from Finish cooking, or manual)
425	CREATE TABLE meal_logs (
426	  id                 uuid NOT NULL DEFAULT gen_random_uuid(),
427	  eaten_at           timestamptz NOT NULL DEFAULT now(),
428	  user_id            uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
