441	) WITH (tsdb.hypertable, tsdb.partition_column = 'eaten_at');
442	CREATE INDEX meal_logs_user_time_idx ON meal_logs (user_id, eaten_at DESC);
443	CREATE INDEX meal_logs_user_date_idx ON meal_logs (user_id, local_date);
444	
445	-- HYPERTABLE: pantry ledger (audit + "usage over time")
446	CREATE TABLE pantry_events (
447	  occurred_at        timestamptz NOT NULL DEFAULT now(),
448	  user_id            uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
449	  pantry_item_id     uuid REFERENCES pantry_items(id) ON DELETE SET NULL,
450	  kind               text NOT NULL CHECK (kind IN ('add','cook_deduct','eat_deduct','manual_adjust','discard')),
451	  delta_base         numeric(12,3) NOT NULL,        -- negative for deductions
452	  cooking_session_id uuid REFERENCES cooking_sessions(id)
453	) WITH (tsdb.hypertable, tsdb.partition_column = 'occurred_at');
454	CREATE INDEX pantry_events_user_time_idx ON pantry_events (user_id, occurred_at DESC);
455	
456	-- CONTINUOUS AGGREGATE: daily nutrition per user
457	CREATE MATERIALIZED VIEW daily_nutrition
458	WITH (timescaledb.continuous) AS
459	SELECT user_id,
460	       time_bucket(INTERVAL '1 day', eaten_at, 'America/Vancouver') AS day,  -- [VERIFY] tz arg in caggs; fallback: drop tz arg (UTC buckets)
461	       sum(kcal)      AS kcal,
462	       sum(protein_g) AS protein_g,
463	       sum(carbs_g)   AS carbs_g,
464	       sum(fat_g)     AS fat_g,
465	       count(*)       AS entries
466	FROM meal_logs
467	GROUP BY user_id, day
468	WITH NO DATA;
469	
470	SELECT add_continuous_aggregate_policy('daily_nutrition',
471	  start_offset => INTERVAL '30 days', end_offset => INTERVAL '1 hour',
472	  schedule_interval => INTERVAL '15 minutes');
473	
474	-- real-time aggregation so "today" includes rows not yet materialized   [VERIFY behaviour]
475	ALTER MATERIALIZED VIEW daily_nutrition SET (timescaledb.materialized_only = false);
476	```
477	
478	Notes and fallbacks:
479	- **"Today" totals** are read from `meal_logs WHERE user_id=$1 AND local_date=$2`, which is exact and cheap. **History (7/30 days)** is read from `daily_nutrition`, the Tiger showcase. Both should agree for Vancouver-time users. A mismatch for users in other time zones is acceptable for the hackathon.
480	- If `WITH (tsdb.hypertable …)` is rejected on the provisioned service, create the plain table and convert it with `SELECT create_hypertable('meal_logs', by_range('eaten_at'));`. **[VERIFY]** That fallback syntax comes from training knowledge and was not checked during research.
481	- Before running migrations, confirm that TimescaleDB is installed on the free service: `SELECT extname, extversion FROM pg_extension;`. Tiger's docs imply that it is unless "plain PostgreSQL" was chosen, but they don't say so explicitly ([Tiger docs: create a service](https://www.tigerdata.com/docs/get-started/quickstart/create-service)).
482	- `scripts/migrate.mjs` applies `db/migrations/*.sql` in order inside a `schema_migrations(version text primary key, applied_at timestamptz)` table it creates itself.
