});

type Env = z.infer<typeof schema>;

let cached: Env | null = null;

/**
 * Validates server env vars with Zod and fails fast. Skipped during `vitest`
 * (NODE_ENV=test) so pure unit tests don't need every production secret —
 * anything that actually calls an external API should mock its own env reads.
 */
export function getEnv(): Env {
  if (cached) return cached;
  if (process.env.NODE_ENV === 'test') {
    cached = schema.partial().parse(process.env) as Env;
    return cached;
  }
  const parsed = schema.safeParse(process.env);
  if (!parsed.success) {
    console.error('[env] invalid/missing environment variables:', parsed.error.flatten().fieldErrors);
    throw new Error('Invalid environment configuration — see logs above.');
  }
  cached = parsed.data;
  return cached;
}

import type { DisplayUnit, UnitDim } from '@/contracts/domain';

interface UnitInfo {
  dim: UnitDim;
  toBase: number; // multiply a quantity in this unit by this to get the base unit
}

const UNITS: Record<DisplayUnit, UnitInfo> = {
  g: { dim: 'mass', toBase: 1 },
  kg: { dim: 'mass', toBase: 1000 },
  oz: { dim: 'mass', toBase: 28.3495 },
  lb: { dim: 'mass', toBase: 453.592 },
  ml: { dim: 'volume', toBase: 1 },
  l: { dim: 'volume', toBase: 1000 },
  tsp: { dim: 'volume', toBase: 4.92892 },
  tbsp: { dim: 'volume', toBase: 14.7868 },
  cup: { dim: 'volume', toBase: 236.588 },
  fl_oz: { dim: 'volume', toBase: 29.5735 },
  pcs: { dim: 'count', toBase: 1 },
};

export function toBase(qty: number, unit: DisplayUnit): { dim: UnitDim; qtyBase: number } | null {
  const info = UNITS[unit];
  if (!info) return null;
  return { dim: info.dim, qtyBase: qty * info.toBase };
}

export function fromBase(qtyBase: number, dim: UnitDim, unit: DisplayUnit): number | null {
  const info = UNITS[unit];
  if (!info || info.dim !== dim) return null;
  return qtyBase / info.toBase;
}

export function convertBetween(
  qtyBase: number,
  from: UnitDim,
  to: UnitDim,
  bridge: { gramsPerUnit?: number | null; densityGPerMl?: number | null },
): number | null {
  if (from === to) return qtyBase;

  const { gramsPerUnit, densityGPerMl } = bridge;

  // Normalize to grams first.
  let grams: number | null;
  if (from === 'mass') grams = qtyBase;
  else if (from === 'count') grams = gramsPerUnit != null ? qtyBase * gramsPerUnit : null;
  else if (from === 'volume') grams = densityGPerMl != null ? qtyBase * densityGPerMl : null;
  else grams = null;

  if (grams == null) return null;

  if (to === 'mass') return grams;
  if (to === 'count') return gramsPerUnit != null ? grams / gramsPerUnit : null;
  if (to === 'volume') return densityGPerMl != null ? grams / densityGPerMl : null;
  return null;
}

const UNIT_ALIASES: Record<string, DisplayUnit> = {
  g: 'g',
  gram: 'g',
  grams: 'g',
  gr: 'g',
  kg: 'kg',
  kilogram: 'kg',
  kilograms: 'kg',
  oz: 'oz',
  ounce: 'oz',
  ounces: 'oz',
  lb: 'lb',
  lbs: 'lb',
  pound: 'lb',
  pounds: 'lb',
  ml: 'ml',
  milliliter: 'ml',
  milliliters: 'ml',
  millilitre: 'ml',
  millilitres: 'ml',
  l: 'l',
  liter: 'l',
  liters: 'l',
  litre: 'l',
  litres: 'l',
  tsp: 'tsp',
  teaspoon: 'tsp',
  teaspoons: 'tsp',
  tbsp: 'tbsp',
  tablespoon: 'tbsp',
  tablespoons: 'tbsp',
  cup: 'cup',
  cups: 'cup',
  floz: 'fl_oz',
  'fl oz': 'fl_oz',
  'fl.oz': 'fl_oz',
  fluidounce: 'fl_oz',
  fluidounces: 'fl_oz',
  pcs: 'pcs',
  pc: 'pcs',
  piece: 'pcs',
  pieces: 'pcs',
  each: 'pcs',
  clove: 'pcs',
  cloves: 'pcs',
  egg: 'pcs',
  eggs: 'pcs',
  count: 'pcs',
};

export function parseUnit(raw: string): DisplayUnit | null {
  const key = raw.trim().toLowerCase().replace(/\.$/, '');
  return UNIT_ALIASES[key] ?? null;
}

const PREFERRED_DISPLAY: Record<UnitDim, DisplayUnit> = { mass: 'g', volume: 'ml', count: 'pcs' };

function roundDisplay(n: number): number {
  return Math.round(n * 100) / 100;
}

export function formatQty(qtyBase: number, dim: UnitDim, preferred?: DisplayUnit): string {
  let unit: DisplayUnit;
  if (preferred && UNITS[preferred].dim === dim) {
    unit = preferred;
  } else if (dim === 'mass') {
    unit = qtyBase >= 1000 ? 'kg' : 'g';
  } else if (dim === 'volume') {
    unit = qtyBase >= 1000 ? 'l' : 'ml';
  } else {
    unit = 'pcs';
  }
  const value = roundDisplay(fromBase(qtyBase, dim, unit) ?? qtyBase);
  return `${value} ${unit === 'pcs' ? 'pcs' : unit}`;
}

import { describe, expect, it } from 'vitest';
import { convertBetween, formatQty, fromBase, parseUnit, toBase } from './units';

describe('toBase / fromBase', () => {
  it('converts every mass factor', () => {
    expect(toBase(1, 'g')).toEqual({ dim: 'mass', qtyBase: 1 });
    expect(toBase(1, 'kg')).toEqual({ dim: 'mass', qtyBase: 1000 });
    expect(toBase(1, 'oz')?.qtyBase).toBeCloseTo(28.3495, 4);
    expect(toBase(1, 'lb')?.qtyBase).toBeCloseTo(453.592, 3);
  });

  it('converts every volume factor', () => {
    expect(toBase(1, 'ml')).toEqual({ dim: 'volume', qtyBase: 1 });
    expect(toBase(1, 'l')).toEqual({ dim: 'volume', qtyBase: 1000 });
    expect(toBase(1, 'tsp')?.qtyBase).toBeCloseTo(4.92892, 4);
    expect(toBase(1, 'tbsp')?.qtyBase).toBeCloseTo(14.7868, 3);
    expect(toBase(1, 'cup')?.qtyBase).toBeCloseTo(236.588, 2);
    expect(toBase(1, 'fl_oz')?.qtyBase).toBeCloseTo(29.5735, 3);
  });

  it('treats count units as 1:1', () => {
    expect(toBase(3, 'pcs')).toEqual({ dim: 'count', qtyBase: 3 });
  });

  it('round-trips cup -> ml -> cup', () => {
    const { qtyBase } = toBase(2, 'cup')!;
    expect(qtyBase).toBeCloseTo(473.176, 2);
    expect(fromBase(qtyBase, 'volume', 'cup')).toBeCloseTo(2, 6);
  });

  it('round-trips kg <-> g', () => {
    const { qtyBase } = toBase(1.5, 'kg')!;
    expect(qtyBase).toBe(1500);
    expect(fromBase(qtyBase, 'mass', 'g')).toBe(1500);
    expect(fromBase(qtyBase, 'mass', 'kg')).toBe(1.5);
  });

  it('rejects a unit from the wrong dimension', () => {
    expect(fromBase(1000, 'mass', 'l')).toBeNull();
  });
});

describe('convertBetween', () => {
  it('is a no-op across the same dimension', () => {
    expect(convertBetween(500, 'mass', 'mass', {})).toBe(500);
  });

  it('bridges count -> mass via gramsPerUnit', () => {
    expect(convertBetween(2, 'count', 'mass', { gramsPerUnit: 50 })).toBe(100);
  });

  it('bridges mass -> count via gramsPerUnit', () => {
    expect(convertBetween(150, 'mass', 'count', { gramsPerUnit: 50 })).toBe(3);
  });

  it('bridges volume -> mass via densityGPerMl', () => {
    expect(convertBetween(100, 'volume', 'mass', { densityGPerMl: 1.03 })).toBeCloseTo(103, 6);
  });

  it('bridges mass -> volume via densityGPerMl', () => {
    expect(convertBetween(103, 'mass', 'volume', { densityGPerMl: 1.03 })).toBeCloseTo(100, 6);
  });

  it('chains count -> volume through grams when both bridges are present', () => {
    expect(convertBetween(2, 'count', 'volume', { gramsPerUnit: 50, densityGPerMl: 1 })).toBe(100);
  });

  it('returns null when no bridge is available', () => {
    expect(convertBetween(2, 'count', 'mass', {})).toBeNull();
    expect(convertBetween(100, 'volume', 'mass', {})).toBeNull();
    expect(convertBetween(2, 'count', 'volume', { gramsPerUnit: 50 })).toBeNull();
  });
});

