export type GtinInvalidReason = 'length' | 'check_digit' | 'non_numeric';
export type GtinValidation = { ok: true; gtin: string } | { ok: false; reason: GtinInvalidReason };

const VALID_LENGTHS = [8, 12, 13, 14];

/** GS1 mod-10 check digit: weight 3 on the digit immediately left of the check digit, alternating. */
function hasValidCheckDigit(digits: string): boolean {
  const nums = digits.split('').map(Number);
  const check = nums[nums.length - 1]!;
  const payload = nums.slice(0, -1);
  let sum = 0;
  for (let i = 0; i < payload.length; i++) {
    const fromRight = payload.length - 1 - i;
    const weight = fromRight % 2 === 0 ? 3 : 1;
    sum += payload[i]! * weight;
  }
  const calculated = (10 - (sum % 10)) % 10;
  return calculated === check;
}

/**
 * Validates a scanned/typed barcode and normalizes it to our canonical
 * GTIN-13/14 (EAN-8 and UPC-A are left-padded with zeros to 13 digits).
 */
export function normalizeGtin(raw: string): GtinValidation {
  const trimmed = raw.trim();
  if (!/^[0-9]+$/.test(trimmed)) return { ok: false, reason: 'non_numeric' };
  if (!VALID_LENGTHS.includes(trimmed.length)) return { ok: false, reason: 'length' };
  if (!hasValidCheckDigit(trimmed)) return { ok: false, reason: 'check_digit' };
  const gtin = trimmed.length === 14 ? trimmed : trimmed.padStart(13, '0');
  return { ok: true, gtin };
}

import { describe, expect, it } from 'vitest';
import { normalizeGtin } from './gtin';

describe('normalizeGtin', () => {
  it('accepts a valid EAN-13 unchanged', () => {
    expect(normalizeGtin('5901234123457')).toEqual({ ok: true, gtin: '5901234123457' });
  });

  it('pads a valid UPC-A to GTIN-13', () => {
    expect(normalizeGtin('036000291452')).toEqual({ ok: true, gtin: '0036000291452' });
  });

  it('pads a valid EAN-8 to GTIN-13', () => {
    expect(normalizeGtin('96385074')).toEqual({ ok: true, gtin: '0000096385074' });
  });

  it('accepts a valid GTIN-14 unchanged', () => {
    expect(normalizeGtin('00036000291452')).toEqual({ ok: true, gtin: '00036000291452' });
  });

  it('rejects a bad check digit', () => {
    expect(normalizeGtin('5901234123450')).toEqual({ ok: false, reason: 'check_digit' });
  });

  it('rejects the wrong length', () => {
    expect(normalizeGtin('123456789')).toEqual({ ok: false, reason: 'length' });
  });

  it('rejects non-numeric input', () => {
    expect(normalizeGtin('590123412345X')).toEqual({ ok: false, reason: 'non_numeric' });
  });

  it('trims surrounding whitespace before validating', () => {
    expect(normalizeGtin('  5901234123457  ')).toEqual({ ok: true, gtin: '5901234123457' });
  });
});

import { NextResponse } from 'next/server';
import type { ZodError } from 'zod';
import type { ApiError, ApiErrorCode } from '@/contracts/api';

const STATUS_BY_CODE: Record<ApiErrorCode, number> = {
  UNAUTHORIZED: 401,
  BAD_REQUEST: 400,
  NOT_FOUND: 404,
  CONFLICT: 409,
  RATE_LIMITED: 429,
  UPSTREAM_UNAVAILABLE: 502,
  UNPROCESSABLE: 422,
  PAYLOAD_TOO_LARGE: 413,
  INTERNAL: 500,
};

export function jsonOk<T>(data: T, init?: ResponseInit) {
  return NextResponse.json(data, init);
}

export function jsonError(code: ApiErrorCode, message: string, details?: unknown): NextResponse<ApiError> {
  return NextResponse.json({ error: { code, message, details } }, { status: STATUS_BY_CODE[code] });
}

export function jsonErrorFromZod(error: ZodError): NextResponse<ApiError> {
  return jsonError('BAD_REQUEST', 'Validation failed', error.flatten());
}

/**
 * Streams one JSON object per line as `application/x-ndjson`. `producer`
 * receives a `write` callback and should await every upstream step before
 * writing the matching event, so clients see progress instead of one
 * buffered burst at the end.
 */
export function ndjsonResponse<T>(producer: (write: (event: T) => void) => Promise<void>): Response {
  const encoder = new TextEncoder();
  const stream = new ReadableStream<Uint8Array>({
    async start(controller) {
      const write = (event: T) => controller.enqueue(encoder.encode(`${JSON.stringify(event)}\n`));
      try {
        await producer(write);
      } catch (err) {
        write({
          type: 'error',
          error: { code: 'INTERNAL', message: err instanceof Error ? err.message : 'Unknown error' },
        } as T);
      } finally {
        controller.close();
      }
    },
  });
  return new Response(stream, {
    headers: {
      'Content-Type': 'application/x-ndjson; charset=utf-8',
      'Cache-Control': 'no-cache',
      'X-Content-Type-Options': 'nosniff',
    },
  });
}

/**
 * In-memory per-user token bucket. Good enough for a single long-lived Node
 * process on one VPS (see SPEC.md §3.1) — would need a shared store (Redis)
 * behind a load balancer.
 */

export const RATE_LIMITS = {
  'recipes/search': 6,
  'recipes/adapt': 6,
  'vision': 10,
  tts: 60,
  'products/lookup': 30,
} as const;

export type RateLimitRoute = keyof typeof RATE_LIMITS;

interface Bucket {
  tokens: number;
  lastRefillMs: number;
}

const buckets = new Map<string, Bucket>();

export interface RateLimitResult {
  ok: boolean;
  retryAfterMs: number;
}

export function checkRateLimit(userId: string, route: RateLimitRoute, now = Date.now()): RateLimitResult {
  const limitPerMinute = RATE_LIMITS[route];
  const key = `${userId}:${route}`;
  const refillPerMs = limitPerMinute / 60_000;

  const existing = buckets.get(key);
  const bucket: Bucket = existing ?? { tokens: limitPerMinute, lastRefillMs: now };
  const elapsedMs = Math.max(0, now - bucket.lastRefillMs);
  bucket.tokens = Math.min(limitPerMinute, bucket.tokens + elapsedMs * refillPerMs);
  bucket.lastRefillMs = now;

  if (bucket.tokens >= 1) {
    bucket.tokens -= 1;
    buckets.set(key, bucket);
    return { ok: true, retryAfterMs: 0 };
  }

  buckets.set(key, bucket);
  const retryAfterMs = Math.ceil((1 - bucket.tokens) / refillPerMs);
  return { ok: false, retryAfterMs };
}

import 'server-only';
import postgres from 'postgres';
import { getEnv } from './env';

const env = getEnv();

/**
 * One small pool per long-lived Node process (SPEC.md §3.1) — Tiger's free
 * tier excludes connection pooling, and postgres.js connects lazily on first
 * query, so constructing this at module load does not open a connection.
 */
const sql = postgres(env.DATABASE_URL ?? '', {
  max: env.DB_POOL_MAX ?? 5,
  ssl: 'require',
});

export default sql;

